import base64
import os
import platform
import subprocess
import tempfile

def GettinStr():
    with open("Leon.mp4", "rb") as video_file:
        encoded_string = base64.b64encode(video_file.read()).decode("utf-8")
    with open("encoded_video.txt", "w") as text_file:
        text_file.write(encoded_string)
        print("Done")


def build_run_script(
    source_txt="encodevd.txt", output_py="run.py"
):
  print("Reading encoded text...")
  with open(source_txt, "r", encoding="utf-8") as f:
    video_b64 = f.read()

  print(f"Building {output_py}...")

  final_code = f"""import base64
import os
import platform
import subprocess
import tempfile

VIDEO_BASE64 = \"\"\"{video_b64}\"\"\"

def run_self_contained_video():
    print("Extracting and launching video...")
    video_bytes = base64.b64decode(VIDEO_BASE64)
    
    with tempfile.NamedTemporaryFile(delete=False, suffix=".mp4") as temp_file:
        temp_file.write(video_bytes)
        temp_file_path = temp_file.name

    current_system = platform.system()
    try:
        if current_system == "Windows":
            os.startfile(temp_file_path)
        elif current_system == "Darwin":
            subprocess.run(["open", temp_file_path], check=True)
        else:
            subprocess.run(["xdg-open", temp_file_path], check=True)
    except Exception as error:
        print(f"Error opening video: {{error}}")

if __name__ == "__main__":
    run_self_contained_video()
"""

  with open(output_py, "w", encoding="utf-8") as f:
    f.write(final_code)

  print(f"SUCCESS! Your '{output_py}' file is fully created and ready.")

VIDEO64 = """"""

def VID():
    print("Extracting and launching video...")
    videobytes = base64.b64decode(VIDEO64)
    
    with tempfile.NamedTemporaryFile(delete=False, suffix=".mp4") as temp_file:
        temp_file.write(videobytes)
        temp_file_path = temp_file.name

    cs = platform.system()
    try:
        if cs == "Windows":
            os.startfile(temp_file_path)
        elif cs == "Darwin":
            subprocess.run(["open", temp_file_path], check=True)
        else:
            subprocess.run(["xdg-open", temp_file_path], check=True)
    except Exception as error:
        print(f"Error opening video: {error}")

if __name__ == "__main__":
    VID()